describe('Expired Promo Code Validation', () => {
  beforeEach(() => {
    cy.visit('/checkout');
  });

  it('should display error message when entering expired promo code', () => {
    // Intercept the API call for promo code validation
    cy.intercept('POST', '/api/promo-code/validate').as('validatePromoCode');

    // Enter a valid promo code
    cy.get('[data-testid="promo-code-input"]').type('SUMMER2024');

    // Click apply button
    cy.get('[data-testid="apply-promo-code-btn"]').click();

    // Wait for API response
    cy.wait('@validatePromoCode').then((interception) => {
      expect(interception.response.statusCode).to.equal(400);
      expect(interception.response.body).to.include('expired');
    });

    // Verify error message is displayed
    cy.get('[data-testid="promo-code-error-message"]')
      .should('be.visible')
      .should('contain', 'This promo code has expired');

    // Verify discount is not applied
    cy.get('[data-testid="discount-amount"]')
      .should('contain', '$0.00');
  });

  it('should handle multiple expired promo codes and display error', () => {
    // Intercept the API call for promo code validation
    cy.intercept('POST', '/api/promo-code/validate').as('validatePromoCode');

    // Enter an expired promo code
    cy.get('[data-testid="promo-code-input"]').type('OLDCODE123');

    // Click apply button
    cy.get('[data-testid="apply-promo-code-btn"]').click();

    // Wait for API response
    cy.wait('@validatePromoCode').then((interception) => {
      expect(interception.response.statusCode).to.equal(400);
      expect(interception.response.body).to.include('expired');
    });

    // Verify error message is displayed
    cy.get('[data-testid="promo-code-error-message"]')
      .should('be.visible')
      .should('contain', 'This promo code has expired');

    // Verify discount is not applied
    cy.get('[data-testid="discount-amount"]')
      .should('contain', '$0.00');

    // Verify user can still proceed with checkout
    cy.get('[data-testid="continue-to-payment-btn"]')
      .should('be.visible')
      .click();
  });
});
